2: 
3: import React, { useState, useRef } from "react";
4: import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
5: import { Button } from "@/components/ui/button";
6: import { Badge } from "@/components/ui/badge";
7: import { Progress } from "@/components/ui/progress";
8: import {
9:   Ghost,
10:   UploadCloud,
11:   Trash2,
12:   Play,
13:   Clock,
14:   AlertTriangle,
15: } from "lucide-react";
16: import { toast } from "sonner";
17: 
18: interface Fragment {
19:   index: number;
20:   payload: string;
21:   size: number;
22: }
23: 
24: export function GhostShell() {
25:   const [loaded, setLoaded] = useState(false);
26:   const [fragments, setFragments] = useState<Fragment[]>([]);
27:   const [ttl, setTtl] = useState(180);
28:   const [logs, setLogs] = useState<string[]>([]);
29:   const timerRef = useRef<NodeJS.Timeout | null>(null);
30: 
31:   const ghostShellBootstrap = `
32: (function ghostShellInit() {
33:     const fragments = {};
34:     let received = 0;
35: 
36:     function addFragment(index, payload) {
37:         if (!fragments[index]) {
38:             fragments[index] = payload;
39:             received++;
40:             console.log(\`[GHOST] Fragment \${index} accepted\`);
41:         }
42:     }
43: 
44:     function assemblePayload() {
45:         const fullPayload = Object.keys(fragments)
46:             .sort((a, b) => a - b)
47:             .map(i => fragments[i])
48:             .join('');
49: 
50:         try {
51:             console.log("[GHOST] Reassembling & executing payload...");
52:             (new Function(atob(fullPayload)))();
53:         } catch (e) {
54:             console.warn("[GHOST] Payload execution error:", e);
55:         }
56:     }
57: 
58:     window.injectGhostFragment = function(index, b64payload) {
59:         addFragment(index, b64payload);
60:     };
61: 
62:     window.assembleGhost = assemblePayload;
63: 
64:     console.log("[GHOST SHELL] Initialized");
65: })();
66: `;
67: 
68:   const addLog = (message: string) => {
69:     setLogs((prev) => [...prev, `[${new Date().toLocaleTimeString()}] ${message}`]);
70:   };
71: 
72:   const loadGhostShell = () => {
73:     try {
74:       // In a real scenario, this would inject into the page
75:       addLog("[GHOST SHELL] Bootstrap code loaded");
76:       addLog("[GHOST SHELL] Memory injection ready");
77:       setLoaded(true);
78: 
79:       // Start TTL countdown
80:       timerRef.current = setInterval(() => {
81:         setTtl((prev) => {
82:           if (prev <= 1) {
83:             purgeGhostShell();
84:             return 0;
85:           }
86:           return prev - 1;
87:         });
88:       }, 1000);
89: 
90:       toast.success("GhostShell loaded into memory");
91:     } catch (e) {
92:       toast.error("Failed to load GhostShell");
93:     }
94:   };
95: 
96:   const purgeGhostShell = () => {
97:     if (timerRef.current) {
98:       clearInterval(timerRef.current);
99:     }
100:     setLoaded(false);
101:     setFragments([]);
102:     setTtl(180);
103:     addLog("[GHOST SHELL] TTL expired. Memory purged.");
104:     toast.info("GhostShell purged from memory");
105:   };
106: 
107:   const handleFileDrop = async (e: React.DragEvent) => {
108:     e.preventDefault();
109:     const file = e.dataTransfer.files[0];
110:     if (!file) return;
111: 
112:     const text = await file.text();
113:     const lines = text.trim().split("\n");
114: 
115:     const newFragments: Fragment[] = lines.map((line, i) => ({
116:       index: i,
117:       payload: line.replace(/[^A-Za-z0-9+/=]/g, ""),
118:       size: line.length,
119:     }));
120: 
121:     setFragments(newFragments);
122:     addLog(`[GHOST] Loaded ${newFragments.length} fragments from file`);
123:     
124:     newFragments.forEach((frag) => {
125:       addLog(`[GHOST] Fragment ${frag.index} accepted (${frag.size} bytes)`);
126:     });
127: 
128:     toast.success(`Injected ${newFragments.length} fragments`);
129:   };
130: 
131:   const executePayload = () => {
132:     if (fragments.length === 0) {
133:       toast.error("No fragments loaded");
134:       return;
135:     }
136: 
137:     addLog("[GHOST] Reassembling payload...");
138:     addLog("[GHOST] Executing assembled payload...");
139:     
140:     // Simulate execution
141:     setTimeout(() => {
142:       addLog("[GHOST] Payload execution complete");
143:       toast.success("Payload executed");
144:     }, 1000);
145:   };
146: 
147:   return (
148:     <Card className="border-red-500/30">
149:       <CardHeader>
150:         <CardTitle className="flex items-center justify-between">
151:           <div className="flex items-center gap-2">
152:             <Ghost className="h-5 w-5 text-red-500" />
153:             GhostShell Module
154:           </div>
155:           {loaded && (
156:             <Badge variant="destructive" className="animate-pulse">
157:               <Clock className="h-3 w-3 mr-1" />
158:               TTL: {Math.floor(ttl / 60)}:{(ttl % 60).toString().padStart(2, "0")}
159:             </Badge>
160:           )}
161:         </CardTitle>
162:       </CardHeader>
163:       <CardContent className="space-y-4">
164:         <div className="p-4 rounded-lg bg-red-950/20 border border-red-500/20">
165:           <div className="flex items-center gap-2 text-red-400 text-sm mb-2">
166:             <AlertTriangle className="h-4 w-4" />
167:             <span>Volatile in-memory payload injector. Self-wipes after TTL.</span>
168:           </div>
169:           <p className="text-xs text-muted-foreground">
170:             Operates fully in-browser. No disk writes. Fragments are base64
171:             encoded and assembled at runtime.
172:           </p>
173:         </div>
174: 
175:         {!loaded ? (
176:           <Button onClick={loadGhostShell} variant="red" className="w-full">
177:             <Ghost className="h-4 w-4 mr-2" />
178:             Load GhostShell
179:           </Button>
180:         ) : (
181:           <>
182:             {/* Fragment Upload */}
183:             <div
184:               onDrop={handleFileDrop}
185:               onDragOver={(e) => e.preventDefault()}
186:               className="border-2 border-dashed border-red-500/30 rounded-lg p-6 text-center hover:border-red-500/50 transition-colors cursor-pointer"
187:             >
188:               <UploadCloud className="h-8 w-8 mx-auto mb-2 text-red-400" />
189:               <p className="text-sm text-muted-foreground">
190:                 Drop .txt with base64 fragments
191:               </p>
192:               {fragments.length > 0 && (
193:                 <Badge variant="outline" className="mt-2">
194:                   {fragments.length} fragments loaded
195:                 </Badge>
196:               )}
197:             </div>
198: 
199:             {/* Fragment List */}
200:             {fragments.length > 0 && (
201:               <div className="space-y-2">
202:                 <div className="flex justify-between text-sm">
203:                   <span>Fragments loaded</span>
204:                   <span>{fragments.length}</span>
205:                 </div>
206:                 <Progress value={(fragments.length / 10) * 100} className="h-2" />
207:               </div>
208:             )}
209: 
210:             {/* Console Output */}
211:             <div className="terminal-output h-40 overflow-y-auto text-xs">
212:               {logs.length === 0 ? (
213:                 <span className="text-gray-500">Awaiting commands...</span>
214:               ) : (
215:                 logs.map((log, i) => (
216:                   <div key={i} className={log.includes("error") ? "error" : ""}>
217:                     {log}
218:                   </div>
219:                 ))
220:               )}
221:             </div>
222: 
223:             {/* Controls */}
224:             <div className="flex gap-2">
225:               <Button
226:                 onClick={executePayload}
227:                 disabled={fragments.length === 0}
228:                 variant="red"
229:                 className="flex-1"
230:               >
231:                 <Play className="h-4 w-4 mr-2" />
232:                 Execute Payload
233:               </Button>
234:               <Button onClick={purgeGhostShell} variant="outline">
235:                 <Trash2 className="h-4 w-4 mr-2" />
236:                 Purge
237:               </Button>
238:             </div>
239:           </>
240:         )}
241:       </CardContent>
242:     </Card>
243:   );
244: }

