3: import React, { useState, useRef, useEffect } from "react";
4: import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
5: import { Button } from "@/components/ui/button";
6: import { Input } from "@/components/ui/input";
7: import { Badge } from "@/components/ui/badge";
8: import { Bug, Send, Trash2, History } from "lucide-react";
9: import { toast } from "sonner";
10: 
11: interface CommandEntry {
12:   id: string;
13:   input: string;
14:   output: string;
15:   timestamp: Date;
16:   status: "success" | "error" | "pending";
17: }
18: 
19: export function ExploitConsole() {
20:   const [command, setCommand] = useState("");
21:   const [history, setHistory] = useState<CommandEntry[]>([]);
22:   const [historyIndex, setHistoryIndex] = useState(-1);
23:   const consoleRef = useRef<HTMLDivElement>(null);
24:   const inputRef = useRef<HTMLInputElement>(null);
25: 
26:   useEffect(() => {
27:     if (consoleRef.current) {
28:       consoleRef.current.scrollTop = consoleRef.current.scrollHeight;
29:     }
30:   }, [history]);
31: 
32:   const simulatedCommands: Record<string, string> = {
33:     help: `Available commands:
34:   scan <target>      - Run vulnerability scan
35:   exploit <module>   - Load exploit module
36:   payload <type>     - Generate payload
37:   sessions           - List active sessions
38:   use <module>       - Use a specific module
39:   set <opt> <value>  - Set module option
40:   run                - Execute current module
41:   exit               - Exit console
42:   clear              - Clear console`,
43:     sessions: `Active Sessions:
44:   ID  Type         Info                    Connection
45:   --  ----         ----                    ----------
46:   1   meterpreter  x64/windows             192.168.1.100:4444 -> 10.0.0.5:49152
47:   2   shell        linux/x64               192.168.1.101:4445 -> 10.0.0.6:38921`,
48:     "scan 192.168.1.0/24": `[*] Starting network scan...
49: [+] Host 192.168.1.1 is up (0.001s latency)
50:     PORT     STATE SERVICE
51:     22/tcp   open  ssh
52:     80/tcp   open  http
53: [+] Host 192.168.1.100 is up (0.002s latency)
54:     PORT     STATE SERVICE
55:     445/tcp  open  microsoft-ds
56:     3389/tcp open  ms-wbt-server
57: [*] Scan complete: 2 hosts up`,
58:     "use exploit/windows/smb/ms17_010": `[*] Loading module: exploit/windows/smb/ms17_010
59: [*] Module options:
60:     RHOSTS    -    Target host(s)
61:     RPORT     445  Target port
62:     PAYLOAD   -    Payload to use`,
63:     run: `[*] Started reverse TCP handler on 10.0.0.1:4444
64: [*] Sending exploit...
65: [+] Exploit completed successfully
66: [*] Meterpreter session 3 opened (10.0.0.1:4444 -> 192.168.1.100:49153)`,
67:     whoami: `NT AUTHORITY\\SYSTEM`,
68:     "systeminfo | findstr /B /C:\"OS\"": `OS Name:                   Microsoft Windows Server 2019
69: OS Version:                10.0.17763 N/A Build 17763`,
70:   };
71: 
72:   const executeCommand = () => {
73:     if (!command.trim()) return;
74: 
75:     const entry: CommandEntry = {
76:       id: Date.now().toString(),
77:       input: command,
78:       output: "",
79:       timestamp: new Date(),
80:       status: "pending",
81:     };
82: 
83:     // Check for built-in commands
84:     if (command === "clear") {
85:       setHistory([]);
86:       setCommand("");
87:       return;
88:     }
89: 
90:     if (command === "exit") {
91:       toast.info("Console session ended");
92:       setCommand("");
93:       return;
94:     }
95: 
96:     // Find matching simulated output
97:     let output = simulatedCommands[command.toLowerCase()];
98:     if (!output) {
99:       // Check for partial matches
100:       const matchKey = Object.keys(simulatedCommands).find((key) =>
101:         command.toLowerCase().startsWith(key.split(" ")[0])
102:       );
103:       output = matchKey
104:         ? simulatedCommands[matchKey]
105:         : `[-] Unknown command: ${command}\nType 'help' for available commands`;
106:     }
107: 
108:     entry.output = output;
109:     entry.status = output.includes("[-]") ? "error" : "success";
110: 
111:     setHistory((prev) => [...prev, entry]);
112:     setCommand("");
113:     setHistoryIndex(-1);
114:   };
115: 
116:   const handleKeyDown = (e: React.KeyboardEvent) => {
117:     if (e.key === "Enter") {
118:       executeCommand();
119:     } else if (e.key === "ArrowUp") {
120:       e.preventDefault();
121:       const commands = history.filter((h) => h.input);
122:       if (commands.length > 0) {
123:         const newIndex = historyIndex < commands.length - 1 ? historyIndex + 1 : historyIndex;
124:         setHistoryIndex(newIndex);
125:         setCommand(commands[commands.length - 1 - newIndex]?.input || "");
126:       }
127:     } else if (e.key === "ArrowDown") {
128:       e.preventDefault();
129:       if (historyIndex > 0) {
130:         const commands = history.filter((h) => h.input);
131:         const newIndex = historyIndex - 1;
132:         setHistoryIndex(newIndex);
133:         setCommand(commands[commands.length - 1 - newIndex]?.input || "");
134:       } else {
135:         setHistoryIndex(-1);
136:         setCommand("");
137:       }
138:     }
139:   };
140: 
141:   return (
142:     <Card className="border-red-500/30">
143:       <CardHeader className="flex flex-row items-center justify-between">
144:         <CardTitle className="flex items-center gap-2">
145:           <Bug className="h-5 w-5 text-red-500" />
146:           Exploit Console
147:         </CardTitle>
148:         <div className="flex gap-2">
149:           <Badge variant="outline" className="font-mono">
150:             {history.length} commands
151:           </Badge>
152:           <Button
153:             size="sm"
154:             variant="ghost"
155:             onClick={() => setHistory([])}
156:           >
157:             <Trash2 className="h-4 w-4" />
158:           </Button>
159:         </div>
160:       </CardHeader>
161:       <CardContent className="space-y-4">
162:         {/* Console Output */}
163:         <div
164:           ref={consoleRef}
165:           className="terminal-output h-80 overflow-y-auto font-mono text-sm"
166:           onClick={() => inputRef.current?.focus()}
167:         >
168:           <div className="text-red-400 mb-2">
169:             ╔══════════════════════════════════════════╗
170:             ║     PURPLE TEAM OPS - EXPLOIT CONSOLE    ║
171:             ╚══════════════════════════════════════════╝
172:           </div>
173:           <div className="text-yellow-400 mb-4">
174:             Type 'help' for available commands
175:           </div>
176: 
177:           {history.map((entry) => (
178:             <div key={entry.id} className="mb-2">
179:               <div className="flex items-center gap-2">
180:                 <span className="text-red-400">exploit</span>
181:                 <span className="text-gray-400">&gt;</span>
182:                 <span className="text-white">{entry.input}</span>
183:               </div>
184:               <pre
185:                 className={`whitespace-pre-wrap ${
186:                   entry.status === "error" ? "text-red-400" : "text-green-400"
187:                 }`}
188:               >
189:                 {entry.output}
190:               </pre>
191:             </div>
192:           ))}
193: 
194:           {/* Current prompt */}
195:           <div className="flex items-center gap-2">
196:             <span className="text-red-400">exploit</span>
197:             <span className="text-gray-400">&gt;</span>
198:             <span className="text-white">{command}</span>
199:             <span className="animate-pulse">▌</span>
200:           </div>
201:         </div>
202: 
203:         {/* Command Input */}
204:         <div className="flex gap-2">
205:           <Input
206:             ref={inputRef}
207:             value={command}
208:             onChange={(e) => setCommand(e.target.value)}
209:             onKeyDown={handleKeyDown}
210:             placeholder="Enter command..."
211:             className="font-mono"
212:             autoFocus
213:           />
214:           <Button onClick={executeCommand} variant="red">
215:             <Send className="h-4 w-4" />
216:           </Button>
217:         </div>
218: 
219:         {/* Quick Commands */}
220:         <div className="flex flex-wrap gap-2">
221:           <span className="text-xs text-muted-foreground">Quick:</span>
222:           {["help", "sessions", "scan 192.168.1.0/24", "use exploit/windows/smb/ms17_010"].map(
223:             (cmd) => (
224:               <Badge
225:                 key={cmd}
226:                 variant="secondary"
227:                 className="cursor-pointer hover:bg-secondary/80 font-mono text-xs"
228:                 onClick={() => {
229:                   setCommand(cmd);
230:                   inputRef.current?.focus();
231:                 }}
232:               >
233:                 {cmd}
234:               </Badge>
235:             )
236:           )}
237:         </div>
238:       </CardContent>
239:     </Card>
240:   );
241: }

