28: interface ScanResult {
29:   type: string;
30:   target: string;
31:   data: Record<string, any>;
32:   timestamp: Date;
33: }
34: 
35: export function ReconModule() {
36:   const [target, setTarget] = useState("");
37:   const [scanning, setScanning] = useState(false);
38:   const [results, setResults] = useState<ScanResult[]>([]);
39: 
40:   const runScan = async (scanType: string) => {
41:     if (!target.trim()) {
42:       toast.error("Enter a target domain or IP");
43:       return;
44:     }
45: 
46:     setScanning(true);
47:     toast.info(`Running ${scanType} scan on ${target}...`);
48: 
49:     // Simulated scan delay
50:     await new Promise((resolve) => setTimeout(resolve, 2000));
51: 
52:     const mockResults: Record<string, Record<string, any>> = {
53:       dns: {
54:         "A Records": ["192.168.1.1", "192.168.1.2"],
55:         "MX Records": ["mail.example.com"],
56:         "NS Records": ["ns1.example.com", "ns2.example.com"],
57:         "TXT Records": ["v=spf1 include:_spf.example.com ~all"],
58:       },
59:       whois: {
60:         Registrar: "Example Registrar Inc.",
61:         Created: "2020-01-15",
62:         Expires: "2025-01-15",
63:         "Name Servers": ["ns1.example.com", "ns2.example.com"],
64:         Status: "clientTransferProhibited",
65:       },
66:       ports: {
67:         "22/tcp": "SSH - OpenSSH 8.2",
68:         "80/tcp": "HTTP - nginx 1.18.0",
69:         "443/tcp": "HTTPS - nginx 1.18.0",
70:         "3306/tcp": "MySQL 8.0.23",
71:         "6379/tcp": "Redis 6.0.10",
72:       },
73:       subdomains: {
74:         Found: [
75:           "www.example.com",
76:           "api.example.com",
77:           "mail.example.com",
78:           "dev.example.com",
79:           "staging.example.com",
80:           "admin.example.com",
81:         ],
82:         "Total Found": 6,
83:       },
84:       headers: {
85:         Server: "nginx/1.18.0",
86:         "X-Powered-By": "Express",
87:         "Content-Security-Policy": "default-src 'self'",
88:         "Strict-Transport-Security": "max-age=31536000",
89:         "X-Frame-Options": "DENY",
90:       },
91:     };
92: 
93:     const result: ScanResult = {
94:       type: scanType,
95:       target,
96:       data: mockResults[scanType] || {},
97:       timestamp: new Date(),
98:     };
99: 
100:     setResults((prev) => [result, ...prev]);
101:     setScanning(false);
102:     toast.success(`${scanType} scan complete`);
103:   };
104: 
105:   const exportResults = () => {
106:     const content = JSON.stringify(results, null, 2);
107:     const blob = new Blob([content], { type: "application/json" });
108:     const url = URL.createObjectURL(blob);
109:     const a = document.createElement("a");
110:     a.href = url;
111:     a.download = `recon_${target}_${Date.now()}.json`;
112:     a.click();
113:     URL.revokeObjectURL(url);
114:     toast.success("Results exported");
115:   };
116: 
117:   return (
118:     <Card className="border-red-500/30">
119:       <CardHeader>
120:         <CardTitle className="flex items-center gap-2">
121:           <Eye className="h-5 w-5 text-red-500" />
122:           Reconnaissance Module
123:         </CardTitle>
124:       </CardHeader>
125:       <CardContent className="space-y-4">
126:         {/* Target Input */}
127:         <div className="flex gap-2">
128:           <Input
129:             placeholder="Enter target domain or IP (e.g., example.com)"
130:             value={target}
131:             onChange={(e) => setTarget(e.target.value)}
132:             className="flex-1"
133:           />
134:           <Button onClick={exportResults} variant="outline" disabled={results.length === 0}>
135:             <FileText className="h-4 w-4 mr-2" />
136:             Export
137:           </Button>
138:         </div>
139: 
140:         {/* Scan Types */}
141:         <Tabs defaultValue="dns">
142:           <TabsList className="grid w-full grid-cols-5">
143:             <TabsTrigger value="dns">
144:               <Globe className="h-4 w-4 mr-1" />
145:               DNS
146:             </TabsTrigger>
147:             <TabsTrigger value="whois">
148:               <Search className="h-4 w-4 mr-1" />
