3: import React, { useState } from "react";
4: import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
5: import { Button } from "@/components/ui/button";
6: import { Input } from "@/components/ui/input";
7: import { Textarea } from "@/components/ui/textarea";
8: import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
9: import { Badge } from "@/components/ui/badge";
10: import { Progress } from "@/components/ui/progress";
11: import {
12:   Code2,
13:   Play,
14:   Plus,
15:   Trash2,
16:   FileText,
17:   Brain,
18:   AlertTriangle,
19: } from "lucide-react";
20: import { toast } from "sonner";
21: 
22: interface Rule {
23:   id: string;
24:   label: string;
25:   pattern: string;
26:   type: "regex" | "yara" | "sigma";
27:   enabled: boolean;
28: }
29: 
30: interface ScanResult {
31:   rule: Rule;
32:   matches: string[];
33:   lineNumbers: number[];
34: }
35: 
36: export function RuleEngine() {
37:   const [rules, setRules] = useState<Rule[]>([
38:     {
39:       id: "1",
40:       label: "Suspicious IP",
41:       pattern: "\\b(?:\\d{1,3}\\.){3}\\d{1,3}\\b",
42:       type: "regex",
43:       enabled: true,
44:     },
45:     {
46:       id: "2",
47:       label: "Base64 Encoded",
48:       pattern: "[A-Za-z0-9+/]{40,}={0,2}",
49:       type: "regex",
50:       enabled: true,
51:     },
52:     {
53:       id: "3",
54:       label: "Malware Keywords",
55:       pattern: "malware|exploit|payload|shellcode|reverse.?shell",
56:       type: "regex",
57:       enabled: true,
58:     },
59:   ]);
60: 
61:   const [newRuleInput, setNewRuleInput] = useState("");
62:   const [scanInput, setScanInput] = useState("");
63:   const [scanResults, setScanResults] = useState<ScanResult[]>([]);
64:   const [mlScore, setMlScore] = useState<number | null>(null);
65:   const [scanning, setScanning] = useState(false);
66: 
67:   const addRule = () => {
68:     const parts = newRuleInput.split("::");
69:     if (parts.length < 2) {
70:       toast.error("Format: Label::pattern");
71:       return;
72:     }
73: 
74:     const [label, pattern] = parts;
75:     const newRule: Rule = {
76:       id: Date.now().toString(),
77:       label: label.trim(),
78:       pattern: pattern.trim(),
79:       type: "regex",
80:       enabled: true,
81:     };
82: 
83:     try {
84:       new RegExp(pattern);
85:       setRules([...rules, newRule]);
86:       setNewRuleInput("");
87:       toast.success(`Rule "${label}" added`);
88:     } catch {
89:       toast.error("Invalid regex pattern");
90:     }
91:   };
92: 
93:   const deleteRule = (id: string) => {
94:     setRules(rules.filter((r) => r.id !== id));
95:     toast.success("Rule deleted");
96:   };
97: 
98:   const toggleRule = (id: string) => {
99:     setRules(
100:       rules.map((r) => (r.id === id ? { ...r, enabled: !r.enabled } : r))
101:     );
102:   };
103: 
104:   const runScan = async () => {
105:     if (!scanInput.trim()) {
106:       toast.error("No input to scan");
107:       return;
108:     }
109: 
110:     setScanning(true);
111:     setScanResults([]);
112:     setMlScore(null);
113: 
114:     await new Promise((resolve) => setTimeout(resolve, 500));
115: 
116:     const results: ScanResult[] = [];
117:     const lines = scanInput.split("\n");
118: 
119:     for (const rule of rules.filter((r) => r.enabled)) {
120:       try {
121:         const regex = new RegExp(rule.pattern, "gi");
122:         const matches: string[] = [];
123:         const lineNumbers: number[] = [];
124: 
125:         lines.forEach((line, idx) => {
126:           const lineMatches = line.match(regex);
127:           if (lineMatches) {
128:             matches.push(...lineMatches);
129:             lineNumbers.push(idx + 1);
130:           }
131:         });
132: 
133:         if (matches.length > 0) {
134:           results.push({ rule, matches, lineNumbers });
135:         }
136:       } catch {
137:         // Skip invalid patterns
138:       }
139:     }
140: 
141:     // Calculate ML score (entropy + keyword density)
142:     const entropy = calculateEntropy(scanInput);
143:     const suspiciousKeywords = (
144:       scanInput.match(/malware|exploit|payload|hack|shell|admin|root|password/gi) || []
145:     ).length;
146:     const score = Math.min(
147:       100,
148:       Math.round(entropy * 10 + suspiciousKeywords * 5 + results.length * 10)
149:     );
150: 
151:     setScanResults(results);
152:     setMlScore(score);
153:     setScanning(false);
154: 
155:     if (results.length > 0) {
156:       toast.warning(`Found ${results.length} rule matches`);
157:     } else {
158:       toast.success("No threats detected");
159:     }
160:   };
161: 
162:   const calculateEntropy = (str: string): number => {
163:     const freq: Record<string, number> = {};
164:     for (const char of str) {
165:       freq[char] = (freq[char] || 0) + 1;
166:     }
167:     let entropy = 0;
168:     const len = str.length;
169:     for (const char in freq) {
170:       const p = freq[char] / len;
171:       entropy -= p * Math.log2(p);
172:     }
173:     return entropy;
174:   };
175: 
176:   return (
177:     <div className="space-y-6">
178:       <Tabs defaultValue="rules" className="w-full">
179:         <TabsList className="grid w-full grid-cols-3">
180:           <TabsTrigger value="rules">
181:             <Code2 className="h-4 w-4 mr-2" />
182:             Rule Builder
183:           </TabsTrigger>
184:           <TabsTrigger value="scan">
185:             <FileText className="h-4 w-4 mr-2" />
186:             Scan Input
187:           </TabsTrigger>
188:           <TabsTrigger value="yara">
189:             <Brain className="h-4 w-4 mr-2" />
190:             YARA Rules
191:           </TabsTrigger>
192:         </TabsList>
193: 
194:         <TabsContent value="rules" className="space-y-4">
195:           <Card>
196:             <CardHeader>
197:               <CardTitle>Add Detection Rule</CardTitle>
198:             </CardHeader>
199:             <CardContent className="space-y-4">
200:               <div className="flex gap-2">
201:                 <Input
202:                   placeholder="Label::regex_pattern (e.g., SQLi::union.*select)"
203:                   value={newRuleInput}
204:                   onChange={(e) => setNewRuleInput(e.target.value)}
205:                   onKeyDown={(e) => e.key === "Enter" && addRule()}
206:                   className="flex-1"
207:                 />
208:                 <Button onClick={addRule} variant="blue">
209:                   <Plus className="h-4 w-4 mr-2" />
210:                   Add Rule
211:                 </Button>
212:               </div>
213:             </CardContent>
214:           </Card>
215: 
216:           <Card>
217:             <CardHeader>
218:               <CardTitle>Active Rules ({rules.length})</CardTitle>
219:             </CardHeader>
220:             <CardContent>
221:               <div className="space-y-2">
222:                 {rules.map((rule) => (
223:                   <div
224:                     key={rule.id}
225:                     className={`flex items-center justify-between p-3 rounded-lg border ${
226:                       rule.enabled ? "bg-card" : "bg-muted opacity-50"
227:                     }`}
228:                   >
229:                     <div className="flex items-center gap-3">
230:                       <input
231:                         type="checkbox"
232:                         checked={rule.enabled}
233:                         onChange={() => toggleRule(rule.id)}
234:                         className="h-4 w-4"
235:                       />
236:                       <div>
237:                         <div className="font-medium">{rule.label}</div>
238:                         <code className="text-xs text-muted-foreground">
239:                           {rule.pattern}
240:                         </code>
241:                       </div>
242:                     </div>
243:                     <div className="flex items-center gap-2">
244:                       <Badge variant="outline">{rule.type}</Badge>
245:                       <Button
246:                         variant="ghost"
247:                         size="icon"
248:                         onClick={() => deleteRule(rule.id)}
249:                       >
250:                         <Trash2 className="h-4 w-4 text-destructive" />
251:                       </Button>
252:                     </div>
253:                   </div>
254:                 ))}
255:               </div>
256:             </CardContent>
257:           </Card>
258:         </TabsContent>
259: 
260:         <TabsContent value="scan" className="space-y-4">
261:           <Card>
262:             <CardHeader>
263:               <CardTitle>Content Scanner</CardTitle>
264:             </CardHeader>
265:             <CardContent className="space-y-4">
266:               <Textarea
267:                 placeholder="Paste suspicious logs, code, or network traffic here..."
268:                 value={scanInput}
269:                 onChange={(e) => setScanInput(e.target.value)}
270:                 className="min-h-[200px] font-mono text-sm"
271:               />
272:               <Button onClick={runScan} disabled={scanning} className="w-full">
273:                 {scanning ? (
274:                   <>
275:                     <div className="animate-spin h-4 w-4 border-2 border-current border-t-transparent rounded-full mr-2" />
276:                     Scanning...
277:                   </>
278:                 ) : (
279:                   <>
280:                     <Play className="h-4 w-4 mr-2" />
281:                     Run Detection Scan
282:                   </>
283:                 )}
284:               </Button>
285:             </CardContent>
286:           </Card>
287: 
288:           {/* Results */}
289:           {(scanResults.length > 0 || mlScore !== null) && (
290:             <Card>
291:               <CardHeader>
292:                 <CardTitle className="flex items-center gap-2">
293:                   <AlertTriangle className="h-5 w-5 text-yellow-500" />
294:                   Scan Results
295:                 </CardTitle>
296:               </CardHeader>
297:               <CardContent className="space-y-4">
298:                 {/* ML Score */}
299:                 {mlScore !== null && (
300:                   <div className="space-y-2">
301:                     <div className="flex justify-between text-sm">
302:                       <span>Threat Score</span>
303:                       <span
304:                         className={
305:                           mlScore >= 70
306:                             ? "text-red-500"
307:                             : mlScore >= 40
308:                             ? "text-yellow-500"
309:                             : "text-green-500"
310:                         }
311:                       >
312:                         {mlScore}/100
313:                       </span>
314:                     </div>
315:                     <Progress
316:                       value={mlScore}
317:                       className="h-2"
318:                       indicatorClassName={
319:                         mlScore >= 70
320:                           ? "bg-red-500"
321:                           : mlScore >= 40
322:                           ? "bg-yellow-500"
323:                           : "bg-green-500"
324:                       }
325:                     />
326:                   </div>
327:                 )}
328: 
329:                 {/* Rule Matches */}
330:                 {scanResults.length > 0 ? (
331:                   <div className="space-y-3">
332:                     {scanResults.map((result, idx) => (
333:                       <div key={idx} className="p-3 rounded-lg bg-destructive/10 border border-destructive/20">
334:                         <div className="flex items-center justify-between mb-2">
335:                           <span className="font-medium">{result.rule.label}</span>
336:                           <Badge variant="destructive">
337:                             {result.matches.length} matches
338:                           </Badge>
339:                         </div>
340:                         <div className="text-xs text-muted-foreground mb-2">
341:                           Lines: {result.lineNumbers.join(", ")}
342:                         </div>
343:                         <div className="flex flex-wrap gap-1">
344:                           {result.matches.slice(0, 5).map((match, i) => (
345:                             <Badge key={i} variant="secondary" className="font-mono text-xs">
346:                               {match.length > 30 ? match.slice(0, 30) + "..." : match}
347:                             </Badge>
348:                           ))}
349:                           {result.matches.length > 5 && (
350:                             <Badge variant="outline">
351:                               +{result.matches.length - 5} more
352:                             </Badge>
353:                           )}
354:                         </div>
355:                       </div>
356:                     ))}
357:                   </div>
358:                 ) : (
359:                   <div className="text-center text-muted-foreground py-4">
360:                     No rule matches found
361:                   </div>
362:                 )}
363:               </CardContent>
364:             </Card>
365:           )}
366:         </TabsContent>
367: 
368:         <TabsContent value="yara" className="space-y-4">
369:           <Card>
370:             <CardHeader>
371:               <CardTitle>YARA Rule Integration</CardTitle>
372:             </CardHeader>
373:             <CardContent className="space-y-4">
374:               <Textarea
375:                 placeholder={`rule suspicious_pe {
376:     meta:
377:         description = "Detects suspicious PE files"
378:         author = "Purple Team"
379:     strings:
380:         $mz = { 4D 5A }
381:         $str1 = "CreateRemoteThread"
382:         $str2 = "VirtualAllocEx"
383:     condition:
384:         $mz at 0 and any of ($str*)
385: }`}
386:                 className="min-h-[300px] font-mono text-sm"
387:               />
388:               <div className="flex gap-2">
389:                 <Button variant="blue" className="flex-1">
390:                   Compile Rule
391:                 </Button>
392:                 <Button variant="outline">Load from File</Button>
393:                 <Button variant="outline">Fetch from GitHub</Button>
394:               </div>
395:               <p className="text-xs text-muted-foreground">
396:                 YARA rules are compiled and executed via the Python backend.
397:                 Ensure the YARA service is running.
398:               </p>
399:             </CardContent>
400:           </Card>
401:         </TabsContent>
402:       </Tabs>
403:     </div>
404:   );
405: }

