import { NextResponse } from "next/server";

interface Alert {
  id: string;
  title: string;
  severity: "critical" | "warning" | "info" | "low";
  description: string;
  source: string;
  timestamp: number;
}

const mockAlerts: Alert[] = [
  {
    id: "1",
    title: "Brute Force Attack Detected",
